<?php
require_once __DIR__.'/config/auth.php';
$dbError='';$err='';
try{$pdo=db();$pdo->exec(file_get_contents(__DIR__.'/sql/schema.sql'));$count=(int)$pdo->query('SELECT COUNT(*) FROM couple_users')->fetchColumn();if($count===0){header('Location:/setup-casal.php');exit;}if(current_user($pdo)){header('Location:/casal.php');exit;}}catch(Throwable $e){$dbError=$e->getMessage();}
if(isset($_GET['logout'])){clear_cookie();header('Location:/login-casal.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$dbError){verify_csrf();$login=trim($_POST['login']??'');$pass=$_POST['password']??'';$s=$pdo->prepare("SELECT id,name,email,password,status,created_at,updated_at FROM couple_users WHERE LOWER(email)=LOWER(:l) OR LOWER(name)=LOWER(:l) LIMIT 1");$s->execute([':l'=>$login]);$u=$s->fetch();if($u&&$u['status']==='active'&&verify_password($pdo,$u,$pass)){require_once __DIR__.'/config/seed.php';seed_couple($pdo,(int)$u['id']);issue_cookie($u);audit($pdo,(int)$u['id'],'login','user',(int)$u['id']);header('Location:/casal.php');exit;}$err='Usuário/e-mail ou senha incorretos.';}
